// One trigger call, four inputs. The Web Scraper API takes an array, so the
// whole date grid is one job with one snapshot to poll - which matters more than
// it sounds: a single search input took 288 seconds in testing on 2026-08-27, so
// four separate jobs would be four independent poll loops on the canvas.
//
// single-item input: Settings emits one row and the grid is built from it.
const cfg = $('Settings').first().json;

const horizons = String(cfg.nights_ahead || '7|21|45|75')
  .split(/[|,\s]+/)
  .map(function (n) { return parseInt(n, 10); })
  .filter(function (n) { return n > 0 && n < 400; });

if (!horizons.length) {
  throw new Error('nights_ahead must be a pipe-separated list of day offsets, for example 7|21|45|75');
}

const stay = Math.max(1, Math.min(14, Number(cfg.stay_nights) || 2));
const guests = Math.max(1, Math.min(8, Number(cfg.guests) || 2));
const market = String(cfg.market_search_term || '').trim();
if (!market) {
  throw new Error('Set market_search_term in Settings, for example: hotels in Austin, TX');
}

// Both of these are case-sensitive enums, and Bright Data rejects a wrong one
// with "This value is not allowed" and no list of what is allowed - so the check
// happens here, where the message can say. Probed live 2026-08-27.
const TYPES = { 'Hotels': 1, 'Vacation rentals': 1, '': 1 };
const SORTS = { 'Relevance': 1, 'Lowest price': 1, 'Highest rating': 1, 'Most reviewed': 1, '': 1 };

const accommodation = String(cfg.accommodation_type === undefined ? 'Hotels' : cfg.accommodation_type);
const sortBy = String(cfg.sort_by === undefined ? 'Relevance' : cfg.sort_by);

if (!TYPES[accommodation]) {
  throw new Error('accommodation_type must be exactly "Hotels" or "Vacation rentals" - it is case sensitive, and "hotels" is rejected. Leave it empty for both.');
}
if (!SORTS[sortBy]) {
  throw new Error('sort_by must be exactly one of "Relevance", "Lowest price", "Highest rating", "Most reviewed" - it is case sensitive. Leave it empty for the default.');
}

// The dataset wants plain YYYY-MM-DD. Building the date by adding milliseconds to
// a UTC midnight avoids the daylight-saving edge that ruins a naive date walk
// once a year in each direction.
const DAY = 86400000;
const base = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00.000Z').getTime();
function iso(offsetDays) {
  return new Date(base + offsetDays * DAY).toISOString().slice(0, 10);
}

const payload = horizons.map(function (h) {
  return {
    search_term: market,
    check_in_date: iso(h),
    check_out_date: iso(h + stay),
    guest_number: guests,
    country: String(cfg.country || 'US'),
    currency: String(cfg.currency || 'USD'),
    sort_by: sortBy,
    accommodation_type: accommodation,
  };
});

return [{ json: {
  payload: payload,
  dates: payload.map(function (p) { return p.check_in_date; }),
  market: market,
  stay_nights: stay,
}}];

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, and neverError means nothing throws. Without this the snapshot id
// is undefined, the progress URL becomes .../progress/undefined, and the failure
// surfaces two nodes later blaming the wrong thing.
//
// single-item input: one trigger call returns one snapshot id.
const res = $input.first().json;

if (res.error || !res.snapshot_id) {
  throw new Error('Bright Data did not accept the search: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: {
  snapshot_id: res.snapshot_id,
  requested_at: new Date().toISOString(),
}}];

// The poll cap lives here rather than on the Wait node, because a Wait has no
// idea how many times it has run. $runIndex is the poll count.
//
// 40 polls at 45 seconds is 30 minutes. That is deliberate: one search input
// took 288 seconds on 2026-08-27, and this job carries four of them.
const MAX_POLLS = Math.max(4, Number($('Settings').first().json.max_polls) || 40);

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check The Job Started').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' was still ' + res.status + ' after ' + attempt +
    ' polls. Raise max_polls in Settings, or shorten nights_ahead.'
  );
}

return [{ json: { status: res.status, attempt: attempt, records: res.records || 0 } }];

// Everything that makes a Google Hotels row usable, and every trap in it.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.hotel_name; });
if (!rows.length) {
  throw new Error('The snapshot came back with no hotel rows. Check market_search_term - it has to be a phrase Google Hotels itself answers, such as "hotels in Austin, TX".');
}

const cfg = $('Settings').first().json;
const wanted = String(cfg.property_name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const minStar = Number(cfg.min_star) || 0;
const maxStar = Number(cfg.max_star) || 5;

// Prices arrive as display strings - "$119", and in other currencies with a
// symbol this code has never seen. Stripping everything that is not a digit or a
// separator is the only parse that survives that, and a thousands comma has to go
// before the decimal point is read or 1,250 becomes 1.25.
function money(s) {
  const t = String(s === null || s === undefined ? '' : s).replace(/[^0-9.,]/g, '');
  if (!t) return null;
  const n = Number(t.replace(/,/g, ''));
  return isFinite(n) && n > 0 ? n : null;
}

function norm(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// Word overlap rather than string equality. Google lists a property under a name
// nobody types - "Holiday Inn Express & Suites Austin NW - Four Points" is not
// what a revenue manager writes in a settings field - so the match is on how much
// of the configured name appears in the listed one.
function matches(name) {
  if (!wanted) return false;
  const a = norm(name);
  if (!a) return false;
  if (a.indexOf(wanted) >= 0) return true;
  const want = wanted.split(' ').filter(function (w) { return w.length > 2; });
  if (!want.length) return false;
  let hit = 0;
  want.forEach(function (w) { if (a.indexOf(w) >= 0) hit++; });
  return hit / want.length >= 0.7;
}

function pct(sorted, p) {
  if (!sorted.length) return null;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  const v = lo === hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
  return Math.round(v);
}

const byDate = {};
let sponsoredDropped = 0;
let starDropped = 0;

rows.forEach(function (r) {
  const date = String(r.check_in_date || '').slice(0, 10);
  if (!date) return;

  // Sponsored rows are advertisements, not the market. Measured 2026-08-27: the
  // one real hotel in the sample returned 76 booking options and the six
  // cheapest were all sponsored. Ranking on the raw minimum makes every comp set
  // look cheaper than it is, which argues for cutting a rate you should hold.
  const opts = (r.booking_options || []).filter(function (o) {
    if (o && o.is_sponsored) { sponsoredDropped++; return false; }
    return true;
  });

  const priced = opts
    .map(function (o) { return { platform: String(o.platform || 'unknown'), price: money(o.price), room: o.room_type || '' }; })
    .filter(function (o) { return o.price !== null; });

  const mine = matches(r.hotel_name);

  // star_classification is null on every vacation rental and a number on hotels.
  // A market search returns both, and an average across them is a confident
  // number about nothing. Your own property is never filtered out - if it falls
  // outside the band, the band is wrong.
  const star = r.star_classification === null || r.star_classification === undefined
    ? null
    : Number(r.star_classification);
  const inBand = star !== null && star >= minStar && star <= maxStar;
  if (!mine && !inBand) { starDropped++; return; }
  if (!priced.length) return;

  const cheapest = priced.reduce(function (a, b) { return a.price <= b.price ? a : b; });
  const dearest = priced.reduce(function (a, b) { return a.price >= b.price ? a : b; });

  if (!byDate[date]) byDate[date] = { date: date, mine: null, comps: [] };
  const entry = {
    hotel: String(r.hotel_name),
    star: star,
    // Seven decimal places of rating is not a rating. review_count arrives as a
    // string and sorts alphabetically if it is left as one.
    rating: r.rating === null || r.rating === undefined ? null : Math.round(Number(r.rating) * 10) / 10,
    reviews: parseInt(String(r.review_count || '0').replace(/[^0-9]/g, ''), 10) || 0,
    cheapest: cheapest.price,
    dearest: dearest.price,
    cheapest_on: cheapest.platform,
    dearest_on: dearest.platform,
    channels: priced.length,
    // Google's idea of the usual rate for this property. It sits ABOVE every
    // live booking option in the same row, so it is context, never the price.
    typical: money(r.price_trend),
    url: String(r.url || ''),
  };
  if (mine) byDate[date].mine = entry;
  else byDate[date].comps.push(entry);
});

const dates = Object.keys(byDate).sort();
if (!dates.length) {
  throw new Error('No rows survived the star filter. Widen min_star and max_star in Settings, or check that the market search term returns hotels rather than rentals.');
}

const out = dates.map(function (d) {
  const g = byDate[d];
  const prices = g.comps.map(function (c) { return c.cheapest; }).sort(function (a, b) { return a - b; });
  const mine = g.mine;
  const rank = mine ? prices.filter(function (p) { return p < mine.cheapest; }).length + 1 : null;

  return { json: {
    date: d,
    comp_count: g.comps.length,
    p25: pct(prices, 0.25),
    median: pct(prices, 0.5),
    p75: pct(prices, 0.75),
    cheapest_comp: prices.length ? prices[0] : null,
    dearest_comp: prices.length ? prices[prices.length - 1] : null,
    found_you: !!mine,
    your_rate: mine ? mine.cheapest : null,
    your_dearest: mine ? mine.dearest : null,
    your_cheapest_on: mine ? mine.cheapest_on : '',
    your_dearest_on: mine ? mine.dearest_on : '',
    your_channels: mine ? mine.channels : 0,
    your_rating: mine ? mine.rating : null,
    rank_of: prices.length ? prices.length + (mine ? 1 : 0) : 0,
    rank: rank,
    // The two headline numbers. Neither is a decision.
    gap_to_median: mine && pct(prices, 0.5) ? mine.cheapest - pct(prices, 0.5) : null,
    channel_spread: mine ? mine.dearest - mine.cheapest : null,
    top_comps: g.comps.sort(function (a, b) { return a.cheapest - b.cheapest; }).slice(0, 5),
    // Run totals, not per-date - they are carried on every row so the report
    // can quote them without a second pass over the snapshot.
    run_sponsored_dropped: sponsoredDropped,
    run_off_band_dropped: starDropped,
  }};
});

return out;

// One item holding a rows array, and a Split Out downstream. A Sheets append in
// autoMapInputData mode writes the item it is given, so handing it this object
// directly would produce one row whose columns are `message`, `rows` and
// `run_at` - a JSON blob in a sheet that promised one row per date.
const stats = $('Work Out Your Position').all().map(function (i) { return i.json; });
// single-item input: the chain above runs with executeOnce and pulls its own
// data by name, so it emits exactly one paragraph for the whole grid.
const note = String(($input.first().json || {}).text || '').trim();
const cfg = $('Settings').first().json;
const grid = $('Build The Date Grid').first().json;
const runAt = new Date().toISOString().slice(0, 10);

const rows = stats.map(function (s) {
  return {
    run_date: runAt,
    check_in: s.date,
    nights: grid.stay_nights,
    property: String(cfg.property_name || ''),
    your_rate: s.your_rate,
    comp_median: s.median,
    comp_p25: s.p25,
    comp_p75: s.p75,
    gap_to_median: s.gap_to_median,
    rank: s.rank,
    comps_compared: s.comp_count,
    channel_spread: s.channel_spread,
    cheapest_channel: s.your_cheapest_on,
    dearest_channel: s.your_dearest_on,
    your_rating: s.your_rating,
    found_in_search: s.found_you ? 'yes' : 'no',
    currency: String(cfg.currency || 'USD'),
  };
});

const missing = stats.filter(function (s) { return !s.found_you; });
const dropped = stats.length ? stats[0].run_sponsored_dropped : 0;
const offBand = stats.length ? stats[0].run_off_band_dropped : 0;

const head = stats.map(function (s) {
  if (!s.found_you) return s.date + ': not listed  [' + s.comp_count + ' comps]';
  const gap = s.gap_to_median === null ? '' :
    (s.gap_to_median > 0 ? ' (+' + s.gap_to_median + ' vs median)' : ' (' + s.gap_to_median + ' vs median)');
  // The comp count is on the headline because a rank of 1 of 6 and a rank of 1
  // of 2 read identically otherwise, and only one of them means anything.
  return s.date + ': ' + s.your_rate + gap + ', #' + (s.rank || '?') + ' of ' +
    s.rank_of + '  [' + s.comp_count + ' comps]';
}).join('\n');

const lines = [];
lines.push('*Rate position* - ' + String(cfg.property_name || 'your property') +
  ', ' + grid.market);
lines.push('```' + head + '```');
if (note) { lines.push(''); lines.push(note); }
lines.push('');
lines.push('_' + dropped + ' sponsored listings and ' + offBand +
  ' off-band properties were excluded. Published rates only - no occupancy, no negotiated rates, no pace._');
if (missing.length) {
  lines.push('_Not found in the search on: ' +
    missing.map(function (m) { return m.date; }).join(', ') + '._');
}

return [{ json: {
  rows: rows,
  row_count: rows.length,
  message: lines.join('\n'),
}}];
